using System;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Windows.Forms;using System.Drawing;
namespace BeamScheduleFormatter {
class RoofSheetQuantity {
 public int Columns,Rows,Pieces;public double CoveredArea,BuyArea,SheetLength,Insulation;
 public static RoofSheetQuantity Calculate(double slope,double width,int quantity,double sheetWidth,double effective,double stock,double lap,bool insulated){RoofMath.Positive(slope,width,sheetWidth,effective);if(quantity<1||quantity>100000||effective>sheetWidth)throw new Exception("Check quantity and widths: effective cover cannot exceed full sheet width.");if(stock==0)stock=slope;RoofMath.Positive(stock);if(double.IsNaN(lap)||double.IsInfinity(lap)||lap<0||lap>=stock)throw new Exception("End lap must be nonnegative and less than sheet length.");int columns=RoofMath.Ceil(width/effective),rows=slope<=stock?1:RoofMath.Ceil((slope-lap)/(stock-lap));int pcs=checked(columns*rows*quantity);return new RoofSheetQuantity{Columns=columns,Rows=rows,Pieces=pcs,SheetLength=stock,CoveredArea=slope*width*quantity,BuyArea=pcs*stock*sheetWidth,Insulation=insulated?slope*width*quantity:0};}
}
class RoofAccessoryQuantity {
 public int Pieces;public double BuyLength,BuyArea,NetLength;
 public static RoofAccessoryQuantity Calculate(double run,int quantity,double developedWidth,double stock,double lap){RoofMath.Positive(run,stock);if(double.IsNaN(developedWidth)||double.IsInfinity(developedWidth)||developedWidth<0)throw new Exception("Developed width cannot be negative.");if(quantity<1||quantity>100000||double.IsNaN(lap)||double.IsInfinity(lap)||lap<0||lap>=stock)throw new Exception("Check quantity and lap; lap must be less than piece length.");int pieces=checked((run<=stock?1:RoofMath.Ceil((run-lap)/(stock-lap)))*quantity);return new RoofAccessoryQuantity{Pieces=pieces,BuyLength=pieces*stock,BuyArea=pieces*stock*developedWidth,NetLength=run*quantity};}
}
static class RoofMath {public static void Positive(params double[] values){foreach(double v in values)if(double.IsNaN(v)||double.IsInfinity(v)||v<=0||v>1000000)throw new Exception("Enter positive finite dimensions.");}public static int Ceil(double v){if(v>1000000)throw new Exception("Quantity exceeds supported limit.");return Math.Max(1,checked((int)Math.Ceiling(v-1e-10)));}}
partial class ProgramOfWorksForm {
 DataGridView roofSheets,roofAccessories;
 void AddRoofing(){roofSheets=Grid(new[]{"Roof ID","Description","Profile","Total roof length m (slope)","Total roof width m","Roof Qty","Full sheet width m","Effective cover m","Order sheet length m (blank=full slope)","End lap mm","Insulation?","Insulation type","Sheets pcs","Roof area m2","Sheet buy m2","Insulation m2","Status"},12);AddCombo(roofSheets,2,"Profile",new[]{"Longspan Rib","Longspan Corrugated"});roofSheets.Columns.RemoveAt(10);roofSheets.Columns.Insert(10,new DataGridViewCheckBoxColumn{Name="Insulation",HeaderText="Insulation?",TrueValue="True",FalseValue="False",ValueType=typeof(string)});roofSheets.Columns[1].Width=220;roofSheets.Columns[2].Width=180;roofSheets.Columns[8].Width=190;roofSheets.Columns[11].Width=180;var sideLap=new DataGridViewComboBoxColumn{Name="CorrugatedLap",HeaderText="Corrugated side lap",Width=150};sideLap.Items.AddRange("1-1/2","2-1/2");roofSheets.Columns.Add(sideLap);var ribSize=new DataGridViewComboBoxColumn{Name="RibSize",HeaderText="Rib side lap",Width=110};ribSize.Items.AddRange("1 rib","2 ribs");roofSheets.Columns.Add(ribSize);sideLap.DisplayIndex=3;ribSize.DisplayIndex=4;roofSheets.Columns[6].ToolTipText="DN Super Hi-Corr nominal: 1.070m; DN Hi-Rib nominal: 1.090m. Purchase area uses full nominal width, without deducting the overlap.";roofSheets.Columns[7].ToolTipText="Reference: Hi-Corr 1.5 lap = 0.970m, 2.5 lap = 0.890m. Hi-Rib: 1-rib lap = 1.030m; 2-rib lap = 0.750m.";
 Action<DataGridViewRow> roofDefaults=r=>{r.Cells[17].Value="2-1/2";r.Cells[18].Value="1 rib";r.Cells[2].Value="Longspan Rib";r.Cells[5].Value="1";r.Cells[9].Value="0";r.Cells[10].Value="True";r.Cells[11].Value="Roof insulation";};roofSheets.DefaultValuesNeeded+=(s,e)=>roofDefaults(e.Row);roofSheets.RowsAdded+=(s,e)=>{if(!filling)for(int n=e.RowIndex;n<e.RowIndex+e.RowCount;n++)if(!roofSheets.Rows[n].IsNewRow&&roofSheets.Rows[n].Cells[5].Value==null)roofDefaults(roofSheets.Rows[n]);};roofSheets.CurrentCellDirtyStateChanged+=(s,e)=>{if(roofSheets.IsCurrentCellDirty)roofSheets.CommitEdit(DataGridViewDataErrorContexts.Commit);};roofSheets.CellValueChanged+=(s,e)=>{if(!filling&&e.RowIndex>=0&&(e.ColumnIndex==2||e.ColumnIndex==10||e.ColumnIndex==17||e.ColumnIndex==18)){Recalculate();}};
 AddGrid("Roofing Sheets & Insulation",roofSheets,"GUIDE: Slope length is the actual inclined roof length including overhang; eave width runs across sheets. DN reference cover widths are automatic: Hi-Corr 970/890mm for 1.5/2.5 side lap (default 2.5); Hi-Rib 1-rib lap 1030mm (default) or 2-rib lap 750mm. Buy area = whole sheets x full nominal width x order length; overlap is not deducted from purchase area. Blank order length = one custom full-slope sheet. Enter fixed order length for stock sheets; end laps and whole-sheet offcuts are included. Insulation is net roof m2, without laps or roll rounding.");
 roofAccessories=Grid(new[]{"Item ID","Description","Type","Run / blank length m","Qty","Developed width mm (optional)","Commercial piece length m","Lap mm","Order pcs","Buy length m","Sheet buy m2","Status"},8);AddCombo(roofAccessories,2,"Type",new[]{"Flashing","Gutter","Ridge Roll","End Flashing Gutter"});roofAccessories.Columns[1].Width=220;roofAccessories.Columns[2].Width=190;Action<DataGridViewRow> accessoryDefaults=r=>{r.Cells[2].Value="Flashing";r.Cells[4].Value="1";r.Cells[6].Value="2.44";r.Cells[7].Value="0";};roofAccessories.DefaultValuesNeeded+=(s,e)=>accessoryDefaults(e.Row);roofAccessories.RowsAdded+=(s,e)=>{if(!filling)for(int n=e.RowIndex;n<e.RowIndex+e.RowCount;n++)if(!roofAccessories.Rows[n].IsNewRow&&roofAccessories.Rows[n].Cells[4].Value==null)accessoryDefaults(roofAccessories.Rows[n]);};
 AddGrid("Flashing & Gutters",roofAccessories,"GUIDE: Enter total installation/run length. Commercial piece length defaults to 2.44m (DPWH metal roofing materials listing); change to match supplier. Enter specified lap to calculate whole-piece purchase length. Developed width is optional, only for supplementary sheet area. End Flashing Gutter uses the actual blank length/width per closure and number of closures (lap=0). No assumed standard dimensions, waste percentage or steel kg.");}
 void RecalculateRoofing(){foreach(var grid in new[]{roofSheets,roofAccessories}){if(grid==null)continue;bool sheet=grid==roofSheets;var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in grid.Rows){if(row.IsNewRow)continue;int first=sheet?12:8,last=sheet?16:11;row.Tag=null;for(int c=first;c<=last;c++)row.Cells[c].Value="";if(Empty(row))continue;try{if(Cell(row,0)==""||Cell(row,1)=="")throw new Exception("Enter ID and description.");if(!ids.Add(Cell(row,0)))throw new Exception("Duplicate roofing ID.");if(sheet){bool corr=Cell(row,2)=="Longspan Corrugated";if(Cell(row,17)=="")row.Cells[17].Value="2-1/2";if(Cell(row,18)==""||Cell(row,18)=="4 ft")row.Cells[18].Value="1 rib";if(Cell(row,18)=="3 ft")row.Cells[18].Value="2 ribs";row.Cells[17].ReadOnly=!corr;row.Cells[18].ReadOnly=corr;row.Cells[7].ReadOnly=true;row.Cells[6].ReadOnly=true;if(corr){if(Cell(row,17)!="1-1/2"&&Cell(row,17)!="2-1/2")throw new Exception("Choose corrugated lap: 1-1/2 or 2-1/2.");row.Cells[6].Value="1.070";row.Cells[7].Value=Cell(row,17)=="1-1/2"?"0.970":"0.890";}else{if(Cell(row,18)!="1 rib"&&Cell(row,18)!="2 ribs")throw new Exception("Choose rib side lap: 1 rib or 2 ribs.");row.Cells[6].Value="1.090";row.Cells[7].Value=Cell(row,18)=="2 ribs"?"0.750":"1.030";}if(Cell(row,2)!="Longspan Rib"&&Cell(row,2)!="Longspan Corrugated")throw new Exception("Choose a roof profile.");bool ins=string.Equals(Cell(row,10),"True",StringComparison.OrdinalIgnoreCase);if(ins&&Cell(row,11)=="")throw new Exception("Enter insulation type or uncheck Insulation.");var q=RoofSheetQuantity.Calculate(Number(row,3),Number(row,4),Count(row,5),Number(row,6),Number(row,7),Cell(row,8)==""?0:Number(row,8),Cell(row,9)==""?0:Number(row,9)/1000,ins);row.Tag=q;row.Cells[12].Value=q.Pieces;row.Cells[13].Value=q.CoveredArea.ToString("0.00");row.Cells[14].Value=q.BuyArea.ToString("0.00");row.Cells[15].Value=q.Insulation.ToString("0.00");}else{if(!new[]{"Flashing","Gutter","Ridge Roll","End Flashing Gutter"}.Contains(Cell(row,2)))throw new Exception("Choose accessory type.");var q=RoofAccessoryQuantity.Calculate(Number(row,3),Count(row,4),Cell(row,5)==""?0:Number(row,5)/1000,Number(row,6),Cell(row,7)==""?0:Number(row,7)/1000);row.Tag=q;row.Cells[8].Value=q.Pieces;row.Cells[9].Value=q.BuyLength.ToString("0.00");row.Cells[10].Value=q.BuyArea.ToString("0.00");}row.Cells[last].Value="Ready";}catch(Exception x){errors.Add("Roofing "+Cell(row,0)+": "+x.Message);row.Cells[last].Value=x.Message;}}}}
 List<object[]> RoofingSummary(){var rows=new List<object[]>();foreach(string type in new[]{"Longspan Rib","Longspan Corrugated"}){var entries=roofSheets.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is RoofSheetQuantity&&Cell(r,2)==type);rows.Add(new object[]{type+" to buy",entries.Sum(r=>((RoofSheetQuantity)r.Tag).BuyArea),"m2"});}foreach(string type in new[]{"Flashing","Gutter","Ridge Roll","End Flashing Gutter"}){var entries=roofAccessories.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is RoofAccessoryQuantity&&Cell(r,2)==type);rows.Add(new object[]{type,entries.Sum(r=>((RoofAccessoryQuantity)r.Tag).BuyLength),"m"});rows.Add(new object[]{type+" pieces",entries.Sum(r=>((RoofAccessoryQuantity)r.Tag).Pieces),"pcs"});rows.Add(new object[]{type+" sheet area",entries.Sum(r=>((RoofAccessoryQuantity)r.Tag).BuyArea),"m2"});}rows.Add(new object[]{"Insulation total (net roof area)",roofSheets.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is RoofSheetQuantity).Sum(r=>((RoofSheetQuantity)r.Tag).Insulation),"m2"});return rows;}
 void RoofingExcel(List<WorksExcelTable> tables){tables.Add(new WorksExcelTable("POW Roofing Summary",new[]{"Item","Quantity","Unit"},RoofingSummary()));var detail=new List<object[]>();foreach(var g in new[]{roofSheets,roofAccessories})foreach(DataGridViewRow r in g.Rows){if(r.Tag is RoofSheetQuantity){var q=(RoofSheetQuantity)r.Tag;detail.Add(new object[]{Cell(r,0),Cell(r,1),Cell(r,2),q.Pieces,q.SheetLength,q.BuyArea,q.CoveredArea,q.Insulation,Cell(r,11)});}if(r.Tag is RoofAccessoryQuantity){var q=(RoofAccessoryQuantity)r.Tag;detail.Add(new object[]{Cell(r,0),Cell(r,1),Cell(r,2),q.Pieces,Number(r,6),q.BuyArea,q.NetLength,0,""});}}tables.Add(new WorksExcelTable("POW Roofing Detail",new[]{"ID","Description","Type","Order pcs","Order length m/pc","Sheet buy m2","Net roof m2 / accessory m","Insulation m2","Insulation type"},detail));}
 void AppendRoofingReport(StringBuilder b,bool detailed){b.AppendLine();b.AppendLine("ROOFING WORKS | PURCHASE SUMMARY");foreach(var item in RoofingSummary())b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-51}{1,14:0.00} {2}",item[0],item[1],item[2]));if(!detailed)return;b.AppendLine();b.AppendLine("SHEETS & INSULATION | BY DESCRIPTION");foreach(DataGridViewRow r in roofSheets.Rows){var q=r.Tag as RoofSheetQuantity;if(q==null)continue;b.AppendLine(Cell(r,0)+" | "+Cell(r,1)+" | "+Cell(r,2));b.AppendLine("  DN profile: "+(Cell(r,2)=="Longspan Corrugated"?"Hi-Corr side lap "+Cell(r,17):"Hi-Rib "+Cell(r,18))+" | Cover "+Cell(r,7)+" m | Nominal "+Cell(r,6)+" m");b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Roof: {0} m slope x {1} m eave x {2} = {3:0.00} m2",Cell(r,3),Cell(r,4),Cell(r,5),q.CoveredArea));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  {0} columns x {1} rows x {2} roofs = {3} sheets @ {4:0.00} m",q.Columns,q.Rows,Cell(r,5),q.Pieces,q.SheetLength));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Buy sheet: {0:0.00} m2 | Insulation: {1:0.00} m2 ({2})",q.BuyArea,q.Insulation,q.Insulation==0?"none":Cell(r,11)));}b.AppendLine();b.AppendLine("FLASHING & GUTTERS | BY DESCRIPTION");foreach(DataGridViewRow r in roofAccessories.Rows){var q=r.Tag as RoofAccessoryQuantity;if(q==null)continue;b.AppendLine(Cell(r,0)+" | "+Cell(r,1)+" | "+Cell(r,2));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Net run: {0:0.00} m | {1} pcs x {2} m = {3:0.00} m to buy",q.NetLength,q.Pieces,Cell(r,6),q.BuyLength));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Developed width: {0} mm | Sheet: {1:0.00} m2 | Lap: {2} mm",Cell(r,5),q.BuyArea,Cell(r,7)));}}
}
